/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  var configsData = api.data.look_up_ssa_config_records.results || [];
  return configsData.map(record => ({
    id: record._row_data.uniqueValue,
    label: record._row_data.displayValue
  }));
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const data = api.data.fetch_deflection_metrics_count.output || {};
    const pageLocale = api.data.overview_locale_get_list.output || {};
    const {
        daysDelta
    } = api.state;
    const {
        fallbackText = '',
        previousDaysText = ''
    } = pageLocale;

    if (data && !data.change && daysDelta > 0) {
        return previousDaysText.replace('{0}', daysDelta);
    } else if (!data) {
        return fallbackText;
    }
    return '';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        daysDelta
    } = api.state;
    const data = api.data.overview_locale_get_list.output;
    if (data) {
        return daysDelta > 0 ? (data.translatedTextLabel.replace('{0}', daysDelta)) : '';
    } else {
        return '';
    }
}

